import{_ as o,a0 as s,w as r,s as p,ao as l,I as a,x as n,a1 as i,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"解决Ubuntu 14.04 Unity桌面环境登录后冻结问题 | LCTT x X-CMD","titleTemplate":false,"description":"解决Ubuntu 14.04 Unity桌面环境登录后冻结问题 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"解决Ubuntu 14.04 Unity桌面环境登录后冻结问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"解决Ubuntu 14.04 Unity桌面环境登录后冻结问题 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Fix Unity Freezes After Login In Ubuntu 14.04 [Quick Tip]","title":"解决Ubuntu 14.04 Unity桌面环境登录后冻结问题","tag":"201405","desc":""},"relativePath":"201405/Fix Unity Freezes After Login In Ubuntu 14.04 [Quick Tip].md","filePath":"[post].md"}'),d={name:"201405/Fix Unity Freezes After Login In Ubuntu 14.04 [Quick Tip].md"};function g(U,t,f,y,b,m){const e=s("Link");return r(),p("div",null,[t[11]||(t[11]=l(`<h1 id="解决ubuntu-14-04-unity桌面环境登录后冻结问题" tabindex="-1">解决Ubuntu 14.04 Unity桌面环境登录后冻结问题 <a class="header-anchor" href="#解决ubuntu-14-04-unity桌面环境登录后冻结问题" aria-label="Permalink to “解决Ubuntu 14.04 Unity桌面环境登录后冻结问题”">​</a></h1><p>如果你把Ubuntu从13.10更新到14.04，你也许会遇到<strong>用Unity桌面环境登录时冻结的现象</strong>。引导进入Ubuntu14.04，输入验证信息，系统会挂起，冻结在那里。如果你稍微幸运些，你还能看到鼠标光标、桌面背景，仅此而已。<strong>没有Unity触发器，也没有顶部面板</strong>等等。你的ubuntu基本上不可用了。</p><p>缺少Unity触发器和面板以及系统冻结的问题，可以通过重新安装Unity来解决。让我们看看怎么做：</p><h3 id="重新安装14-04的unity-以解决系统冻结的问题" tabindex="-1">重新安装14.04的Unity 以解决系统冻结的问题### <a class="header-anchor" href="#重新安装14-04的unity-以解决系统冻结的问题" aria-label="Permalink to “重新安装14.04的Unity 以解决系统冻结的问题###”">​</a></h3><p>好吧，如果你正被困在一个冻结的系统上，按下<strong>Ctrl+Alt+F2</strong>。这会让你进入一个命令行界面而不是默认的用户桌面界面。切换到命令行界面后，输入用户名和密码登录之后，使用下面的命令重装Unity桌面环境：</p><pre><code>sudo apt-get update
sudo apt-get install –reinstall ubuntu-desktop
sudo apt-get install unity
sudo shutdown -r now
</code></pre><p>最后一个命令是重启系统，重启之后，你的Unity应该就变好了。</p><h3 id="解决nvidia显卡的unity冻结问题" tabindex="-1">解决Nvidia显卡的Unity冻结问题### <a class="header-anchor" href="#解决nvidia显卡的unity冻结问题" aria-label="Permalink to “解决Nvidia显卡的Unity冻结问题###”">​</a></h3><p>我没有使用过Nvidia的显卡，但是我找到了别人解决这个问题的方法。尽管上面的技巧对我来说有效，但是我没有过验证下面的命令。使用Nvidia的用户，请告诉我下面的步骤是否工作：</p><p>和上面一样使用<strong>Ctrl+Alt+F2</strong>登录到命令行界面，输入下面的命令：</p><pre><code>sudo apt-get update
sudo apt-get install –reinstall ubuntu-desktop
sudo apt-get install unity
sudo apt-get remove –purge nvidia*
sudo shutdown -r now
</code></pre><p>如果重启之后Unity恢复了，记得重新安装你的Nvidia显卡的驱动，因为你已经卸载了它。</p><p>我希望这些技巧能够帮助你从冻结的unbuntu 14.04中恢复。最后，任何的问题和建议都欢迎来提。</p><hr>`,14)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),i(e,{href:"http://itsfoss.com/fix-unity-freezes-after-login-ubuntu-14-04/"},{default:u(()=>[...t[0]||(t[0]=[n("http://itsfoss.com/fix-unity-freezes-after-login-ubuntu-14-04/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=n("译者：",-1)),i(e,{href:"https://github.com/ggaaooppeenngg"},{default:u(()=>[...t[2]||(t[2]=[n("ggaaooppeenngg",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:u(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const _=o(d,[["render",g]]);export{C as __pageData,_ as default};
